"""Source-bound release evidence validation (ADR-004).

Runtime provenance contract:
- run start: ``<evidence>/<TICKER>/<mode>/provenance.json``
- judge time: ``<evidence>/judge/<TICKER>/<mode>/provenance.json``
Each file holds ``{"source_fingerprint", "model", "provider"}``. The gate reads
per-case/per-arm files and never trusts an aggregate PASS.
"""

from __future__ import annotations

import hashlib
import json
from pathlib import Path
from typing import Any

from ..config import DEFAULT_MODEL, DEFAULT_PROVIDER

MODES = ("baseline", "compact")
PROVENANCE = "provenance.json"
MANDATORY = (
    "instrument_identity",
    "analysis_date",
    "final_decision_present",
    "frozen_price_in_report",
    "source_id_referenced",
)
SETTINGS = (
    "llm_provider",
    "quick_think_llm",
    "deep_think_llm",
    "max_tokens",
    "temperature",
    "llm_max_retries",
    "max_debate_rounds",
    "max_risk_discuss_rounds",
    "extra_body",
    "backend_url",
    "checkpoint_enabled",
)
MIN_SUPPORT = 0.8
MIN_RELEVANCE = 0.8
MIN_CITATION = 0.95
COST_MIN = 0.20
QUALITY_DROP_MAX = 0.05
WALL_MAX = 1.10


def _source_paths(root: Path) -> list[Path]:
    root = Path(root)
    paths: list[Path] = []
    for pattern in ("src/research_desk/**/*.py", "prompts/**/*.yaml", "prompts/**/*.yml"):
        found = [p for p in root.glob(pattern) if p.is_file()]
        if not found:
            raise FileNotFoundError(f"required source files {pattern!r} missing under {root}")
        paths.extend(found)
    for rel in ("pyproject.toml", "requirements-lock.txt", "test/fixtures/market/orchestration-manifest.json"):
        path = root / rel
        if not path.is_file():
            raise FileNotFoundError(f"required source file missing: {path}")
        paths.append(path)
    market = [p for p in (root / "test/fixtures/market").glob("*.csv") if p.is_file()]
    if not market:
        raise FileNotFoundError(f"required market CSV corpus missing under {root}")
    paths.extend(market)
    return sorted(paths, key=lambda p: p.relative_to(root).as_posix())


def source_fingerprint(root: Path) -> str:
    """SHA-256 of sorted relative runtime filenames plus their contents."""
    root = Path(root).resolve()
    digest = hashlib.sha256()
    for path in _source_paths(root):
        digest.update(path.relative_to(root).as_posix().encode("utf-8"))
        digest.update(b"\0")
        digest.update(hashlib.sha256(path.read_bytes()).digest())
    return "sha256:" + digest.hexdigest()


def _json(path: Path, label: str, failures: list[str]) -> Any:
    try:
        return json.loads(Path(path).read_text(encoding="utf-8"))
    except Exception as exc:  # noqa: BLE001
        failures.append(f"{label}: cannot read {Path(path).name}: {exc}")
        return None


def _num(value: Any) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _settings(config: dict[str, Any]) -> dict[str, Any]:
    return {key: config.get(key) for key in SETTINGS}


def _by_name(checks: Any) -> dict[str, dict[str, Any]]:
    if not isinstance(checks, list):
        return {}
    return {c["check"]: c for c in checks if isinstance(c, dict) and isinstance(c.get("check"), str)}


def _quality(judge: dict[str, Any]) -> float | None:
    values = [judge.get(k) for k in ("support", "relevance", "valid_citation_rate")]
    if not all(_num(v) for v in values):
        return None
    return sum(float(v) for v in values) / 3


def _provenance(rec: Any, current: str | None, label: str, kind: str, failures: list[str]) -> None:
    if not isinstance(rec, dict):
        failures.append(f"{label}: {kind} provenance is not an object")
        return
    if current is None or rec.get("source_fingerprint") != current:
        failures.append(f"{label}: {kind} provenance has a stale or incorrect source fingerprint")
    if rec.get("model") != DEFAULT_MODEL:
        failures.append(f"{label}: {kind} provenance model {rec.get('model')!r} != {DEFAULT_MODEL!r}")
    if rec.get("provider") != DEFAULT_PROVIDER:
        failures.append(f"{label}: {kind} provenance provider {rec.get('provider')!r} != {DEFAULT_PROVIDER!r}")


def _summary(summary: dict[str, Any], ticker: str, mode: str, label: str, failures: list[str]) -> None:
    if str(summary.get("ticker", "")).upper() != ticker:
        failures.append(f"{label}: summary ticker mismatch")
    if summary.get("context_mode") != mode:
        failures.append(f"{label}: summary context_mode mismatch")
    if summary.get("outcome") != "completed":
        failures.append(f"{label}: outcome is not completed")
    if summary.get("pack_complete") is not True:
        failures.append(f"{label}: pack_complete is not true")
    if summary.get("error") not in (None, "", False):
        failures.append(f"{label}: summary records an error")
    for key in ("calls", "input_tokens", "output_tokens", "total_tokens"):
        if not _num(summary.get(key)) or summary[key] <= 0:
            failures.append(f"{label}: {key} is not positive recorded usage")
    if all(_num(summary.get(k)) for k in ("total_tokens", "input_tokens", "output_tokens")):
        if summary["total_tokens"] != summary["input_tokens"] + summary["output_tokens"]:
            failures.append(f"{label}: summary total_tokens != input + output")
    if not _num(summary.get("wall_seconds")) or summary["wall_seconds"] < 0:
        failures.append(f"{label}: wall_seconds is missing or negative")


def _pack(pack: Any, summary: dict[str, Any], ticker: str, mode: str, case: dict, label: str, failures: list[str]) -> dict[str, dict[str, Any]]:
    if not pack.complete:
        failures.append(f"{label}: saved actual pack is incomplete")
    if pack.manifest.outcome != "completed":
        failures.append(f"{label}: saved actual pack outcome is not completed")
    if str(pack.manifest.ticker).upper() != ticker or pack.manifest.context_mode != mode:
        failures.append(f"{label}: saved actual pack identity/mode mismatch")
    usage = pack.usage
    for key in ("calls", "input_tokens", "output_tokens", "total_tokens"):
        value = getattr(usage, key)
        if not _num(value) or value <= 0:
            failures.append(f"{label}: saved pack {key} is not positive recorded usage")
        if summary.get(key) != value:
            failures.append(f"{label}: summary {key} does not match the saved actual pack")
    if usage.total_tokens != usage.input_tokens + usage.output_tokens:
        failures.append(f"{label}: saved pack total_tokens != input + output")
    try:
        from .live import _deterministic_checks

        return _by_name(_deterministic_checks(case, pack, ticker))
    except Exception as exc:  # noqa: BLE001
        failures.append(f"{label}: cannot recompute checks from saved actual pack: {exc}")
        return {}


def _judge(judge: dict[str, Any], recomputed: dict[str, dict[str, Any]], label: str, failures: list[str]) -> None:
    if judge.get("error") is not False:
        failures.append(f"{label}: judge error is not false")
    if not _num(judge.get("support")) or judge["support"] < MIN_SUPPORT:
        failures.append(f"{label}: support below {MIN_SUPPORT}")
    if not _num(judge.get("relevance")) or judge["relevance"] < MIN_RELEVANCE:
        failures.append(f"{label}: relevance below {MIN_RELEVANCE}")
    if not _num(judge.get("valid_citation_rate")) or judge["valid_citation_rate"] < MIN_CITATION:
        failures.append(f"{label}: valid_citation_rate below {MIN_CITATION}")
    if judge.get("semantic_valid") is not True:
        failures.append(f"{label}: semantic_valid is not true")
    if judge.get("semantic_errors") != []:
        failures.append(f"{label}: semantic_errors is not empty")
    saved = _by_name(judge.get("deterministic_checks"))
    for name in MANDATORY:
        if name not in saved:
            failures.append(f"{label}: mandatory deterministic check missing: {name}")
        elif saved[name].get("passed") is not True:
            failures.append(f"{label}: deterministic check failed: {name}")
        if recomputed:
            actual = recomputed.get(name)
            if actual is None or actual.get("passed") is not True:
                failures.append(f"{label}: recomputed pack check failed: {name}")
            elif name in saved and saved[name].get("passed") != actual.get("passed"):
                failures.append(f"{label}: saved check disagrees with saved actual pack: {name}")


def validate_release(root: Path, evidence_dir: Path) -> dict[str, Any]:
    """Validate current-source release evidence; returns failures and metrics."""
    root = Path(root).resolve()
    evidence = Path(evidence_dir)
    if not evidence.is_absolute():
        evidence = root / evidence
    failures: list[str] = []
    checks: list[str] = []
    warnings: list[str] = []
    metrics: dict[str, Any] = {"cases": {}}
    try:
        current: str | None = source_fingerprint(root)
        checks.append(f"RELEASE_SOURCE_FINGERPRINT={current}")
    except Exception as exc:  # noqa: BLE001
        current = None
        failures.append(f"source fingerprint unavailable: {exc}")
    from .case_registry import all_cases

    cases = {c["ticker"].upper(): c for c in all_cases()}
    expected = set(cases)
    if not evidence.is_dir():
        failures.append(f"release evidence directory missing: {evidence}")
        return {"failures": failures, "checks": checks, "warnings": warnings, "metrics": metrics}
    present = {p.name.upper() for p in evidence.iterdir() if p.is_dir() and p.name not in {"judge", "aggregate"}}
    for ticker in sorted(expected - present):
        failures.append(f"missing expected case: {ticker}")
    for ticker in sorted(present - expected):
        failures.append(f"unexpected case identity: {ticker}")
    checks.append(f"RELEASE_CASES={len(expected)}")

    arms: dict[str, dict[str, Any]] = {}
    for ticker, case in cases.items():
        arms[ticker] = {}
        for mode in MODES:
            label = f"{ticker}/{mode}"
            arm = evidence / ticker / mode
            if not arm.is_dir():
                failures.append(f"{label}: arm missing")
                continue
            summary = _json(arm / "summary.json", label, failures)
            config = _json(arm / "config.json", label, failures)
            prov = _json(arm / PROVENANCE, label, failures)
            judge = _json(evidence / "judge" / ticker / mode / "judge.json", label, failures)
            jprov = _json(evidence / "judge" / ticker / mode / PROVENANCE, label, failures)
            if not all(isinstance(x, dict) for x in (summary, config, prov, judge, jprov)):
                continue
            _provenance(prov, current, label, "run", failures)
            _provenance(jprov, current, label, "judge", failures)
            _summary(summary, ticker, mode, label, failures)
            for key in ("llm_provider", "quick_think_llm", "deep_think_llm"):
                if not config.get(key):
                    failures.append(f"{label}: config missing {key}")
            if config.get("llm_provider") != prov.get("provider"):
                failures.append(f"{label}: config provider != run provenance provider")
            if config.get("quick_think_llm") != prov.get("model") or config.get("deep_think_llm") != prov.get("model"):
                failures.append(f"{label}: config model fields != run provenance model")
            if config.get("quick_think_llm") != DEFAULT_MODEL or config.get("deep_think_llm") != DEFAULT_MODEL:
                failures.append(f"{label}: config model is not current {DEFAULT_MODEL!r}")
            recomputed: dict[str, dict[str, Any]] = {}
            try:
                from ..evidence import EvidencePackIO

                pack = EvidencePackIO().import_pack(arm / "run")
                recomputed = _pack(pack, summary, ticker, mode, case, label, failures)
            except Exception as exc:  # noqa: BLE001
                failures.append(f"{label}: saved actual pack cannot be loaded: {exc}")
            _judge(judge, recomputed, label, failures)
            arms[ticker][mode] = {"summary": summary, "config": config, "prov": prov, "judge": judge, "jprov": jprov}

        baseline = arms[ticker].get("baseline")
        compact = arms[ticker].get("compact")
        if not baseline or not compact:
            continue
        if (baseline["prov"].get("model"), baseline["prov"].get("provider")) != (
            compact["prov"].get("model"), compact["prov"].get("provider")
        ):
            failures.append(f"{ticker}: run model/provider differ across arms")
        if _settings(baseline["config"]) != _settings(compact["config"]):
            failures.append(f"{ticker}: settings differ across arms")
        if (baseline["jprov"].get("model"), baseline["jprov"].get("provider")) != (
            compact["jprov"].get("model"), compact["jprov"].get("provider")
        ):
            failures.append(f"{ticker}: judge model/provider differ across arms")
        if (baseline["prov"].get("model"), baseline["prov"].get("provider")) != (
            baseline["jprov"].get("model"), baseline["jprov"].get("provider")
        ):
            failures.append(f"{ticker}: judge provenance does not match run provenance")
        metrics["cases"][ticker] = {
            "baseline_tokens": baseline["summary"].get("total_tokens"),
            "compact_tokens": compact["summary"].get("total_tokens"),
            "baseline_wall_seconds": baseline["summary"].get("wall_seconds"),
            "compact_wall_seconds": compact["summary"].get("wall_seconds"),
            "baseline_quality": _quality(baseline["judge"]),
            "compact_quality": _quality(compact["judge"]),
        }

    paired = [
        m for m in metrics["cases"].values()
        if None not in (
            m["baseline_tokens"], m["compact_tokens"], m["baseline_wall_seconds"],
            m["compact_wall_seconds"], m["baseline_quality"], m["compact_quality"],
        )
    ]
    if paired:
        baseline_tokens = sum(m["baseline_tokens"] for m in paired)
        compact_tokens = sum(m["compact_tokens"] for m in paired)
        baseline_wall = sum(m["baseline_wall_seconds"] for m in paired)
        compact_wall = sum(m["compact_wall_seconds"] for m in paired)
        reduction = 1 - compact_tokens / baseline_tokens if baseline_tokens > 0 else None
        ratio = compact_wall / baseline_wall if baseline_wall > 0 else None
        baseline_quality = sum(m["baseline_quality"] for m in paired) / len(paired)
        compact_quality = sum(m["compact_quality"] for m in paired) / len(paired)
        drop = baseline_quality - compact_quality
        metrics["aggregate"] = {
            "token_reduction": reduction,
            "mean_quality_baseline": baseline_quality,
            "mean_quality_compact": compact_quality,
            "mean_quality_drop": drop,
            "wall_ratio": ratio,
        }
        metrics["should_targets"] = {
            "token_reduction": {"value": reduction, "target": f">={COST_MIN}", "passed": reduction is not None and reduction >= COST_MIN},
            "mean_quality_drop": {"value": drop, "target": f"<={QUALITY_DROP_MAX}", "passed": drop <= QUALITY_DROP_MAX},
            "wall_ratio": {"value": ratio, "target": f"<={WALL_MAX}", "passed": ratio is not None and ratio <= WALL_MAX},
        }
        for name, target in metrics["should_targets"].items():
            status = "PASS" if target["passed"] else "FAIL"
            checks.append(f"RELEASE_SHOULD {name}={target['value']} target {target['target']} {status}")
            if not target["passed"] and name != "mean_quality_drop":
                warnings.append(f"Should target missed: {name}={target['value']} target {target['target']}")
        if drop > QUALITY_DROP_MAX:
            failures.append(f"quality retention failed: mean quality drop {drop:.4f} > {QUALITY_DROP_MAX}")

    return {
        "failures": failures,
        "checks": checks,
        "warnings": warnings,
        "metrics": metrics,
        "source_fingerprint": current,
    }

"""Source-bound release evidence validation (ADR-004).

Run: <evidence>/<TICKER>/<mode>/provenance.json; judge:
<evidence>/judge/<TICKER>/<mode>/provenance.json. Each holds
{"source_fingerprint","model","provider"}. Aggregate PASS is ignored.
"""

from __future__ import annotations

import hashlib
import json
from pathlib import Path
from typing import Any

from ..config import DEFAULT_MODEL, DEFAULT_PROVIDER

MODES = ("baseline", "compact")
PROVENANCE = "provenance.json"
MANDATORY = ("instrument_identity", "analysis_date", "final_decision_present", "frozen_price_in_report", "source_id_referenced")
SETTINGS = ("llm_provider", "quick_think_llm", "deep_think_llm", "max_tokens", "temperature", "llm_max_retries", "max_debate_rounds", "max_risk_discuss_rounds", "extra_body", "backend_url", "checkpoint_enabled")
MIN_SUPPORT = MIN_RELEVANCE = 0.8
MIN_CITATION = 0.95
COST_MIN, QUALITY_DROP_MAX, WALL_MAX = 0.20, 0.05, 1.10


def _source_paths(root: Path) -> list[Path]:
    root = Path(root)
    paths: list[Path] = []
    for pattern in ("src/research_desk/**/*.py", "prompts/**/*.yaml", "prompts/**/*.yml"):
        found = [p for p in root.glob(pattern) if p.is_file()]
        if not found:
            raise FileNotFoundError(f"required source files {pattern!r} missing under {root}")
        paths.extend(found)
    for rel in ("pyproject.toml", "requirements-lock.txt", "test/fixtures/market/orchestration-manifest.json"):
        path = root / rel
        if not path.is_file():
            raise FileNotFoundError(f"required source file missing: {path}")
        paths.append(path)
    market = [p for p in (root / "test/fixtures/market").glob("*.csv") if p.is_file()]
    if not market:
        raise FileNotFoundError(f"required market CSV corpus missing under {root}")
    paths.extend(market)
    return sorted(paths, key=lambda p: p.relative_to(root).as_posix())


def source_fingerprint(root: Path) -> str:
    """SHA-256 of sorted relative runtime filenames plus contents."""
    root = Path(root).resolve()
    digest = hashlib.sha256()
    for path in _source_paths(root):
        digest.update(path.relative_to(root).as_posix().encode("utf-8"))
        digest.update(b"\0")
        digest.update(hashlib.sha256(path.read_bytes()).digest())
    return "sha256:" + digest.hexdigest()


def _json(path: Path, label: str, failures: list[str]) -> Any:
    try:
        return json.loads(Path(path).read_text(encoding="utf-8"))
    except Exception as exc:  # noqa: BLE001
        failures.append(f"{label}: cannot read {Path(path).name}: {exc}")
        return None


def _num(value: Any) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _by_name(checks: Any) -> dict[str, dict[str, Any]]:
    if not isinstance(checks, list):
        return {}
    return {c["check"]: c for c in checks if isinstance(c, dict) and isinstance(c.get("check"), str)}


def _quality(judge: dict[str, Any]) -> float | None:
    values = [judge.get(k) for k in ("support", "relevance", "valid_citation_rate")]
    return sum(float(v) for v in values) / 3 if all(_num(v) for v in values) else None


def _provenance(rec: Any, current: str | None, label: str, kind: str, failures: list[str]) -> None:
    if not isinstance(rec, dict):
        failures.append(f"{label}: {kind} provenance is not an object")
        return
    if current is None or rec.get("source_fingerprint") != current:
        failures.append(f"{label}: {kind} provenance has a stale or incorrect source fingerprint")
    for key, expected in (("model", DEFAULT_MODEL), ("provider", DEFAULT_PROVIDER)):
        if rec.get(key) != expected:
            failures.append(f"{label}: {kind} provenance {key} {rec.get(key)!r} != {expected!r}")


def _summary(summary: dict[str, Any], ticker: str, mode: str, label: str, failures: list[str]) -> None:
    for key, expected in (("ticker", ticker), ("context_mode", mode), ("outcome", "completed")):
        got = summary.get(key)
        if (str(got).upper() if key == "ticker" else got) != expected:
            failures.append(f"{label}: summary {key} mismatch")
    if summary.get("pack_complete") is not True:
        failures.append(f"{label}: pack_complete is not true")
    if summary.get("error") not in (None, "", False):
        failures.append(f"{label}: summary records an error")
    usage = [summary.get(k) for k in ("calls", "input_tokens", "output_tokens", "total_tokens")]
    if any(not _num(v) or v <= 0 for v in usage):
        failures.append(f"{label}: usage is not positive recorded usage")
    if all(_num(v) for v in usage[1:]) and usage[3] != usage[1] + usage[2]:
        failures.append(f"{label}: summary total_tokens != input + output")
    if not _num(summary.get("wall_seconds")) or summary["wall_seconds"] < 0:
        failures.append(f"{label}: wall_seconds is missing or negative")


def _pack(pack: Any, summary: dict[str, Any], ticker: str, mode: str, case: dict, label: str, failures: list[str]) -> dict[str, dict[str, Any]]:
    if not pack.complete:
        failures.append(f"{label}: saved actual pack is incomplete")
    if pack.manifest.outcome != "completed":
        failures.append(f"{label}: saved actual pack outcome is not completed")
    if str(pack.manifest.ticker).upper() != ticker or pack.manifest.context_mode != mode:
        failures.append(f"{label}: saved actual pack identity/mode mismatch")
    usage = pack.usage
    values = {k: getattr(usage, k) for k in ("calls", "input_tokens", "output_tokens", "total_tokens")}
    if any(not _num(v) or v <= 0 for v in values.values()):
        failures.append(f"{label}: saved pack usage is not positive recorded usage")
    for key, value in values.items():
        if summary.get(key) != value:
            failures.append(f"{label}: summary {key} does not match the saved actual pack")
    if usage.total_tokens != usage.input_tokens + usage.output_tokens:
        failures.append(f"{label}: saved pack total_tokens != input + output")
    try:
        from .live import _deterministic_checks
        return _by_name(_deterministic_checks(case, pack, ticker))
    except Exception as exc:  # noqa: BLE001
        failures.append(f"{label}: cannot recompute checks from saved actual pack: {exc}")
        return {}


def _judge(judge: dict[str, Any], recomputed: dict[str, dict[str, Any]], label: str, failures: list[str]) -> None:
    if judge.get("error") is not False:
        failures.append(f"{label}: judge error is not false")
    for key, minimum in (("support", MIN_SUPPORT), ("relevance", MIN_RELEVANCE), ("valid_citation_rate", MIN_CITATION)):
        if not _num(judge.get(key)) or judge[key] < minimum:
            failures.append(f"{label}: {key} below {minimum}")
    if judge.get("semantic_valid") is not True:
        failures.append(f"{label}: semantic_valid is not true")
    if judge.get("semantic_errors") != []:
        failures.append(f"{label}: semantic_errors is not empty")
    saved = _by_name(judge.get("deterministic_checks"))
    for name in MANDATORY:
        if name not in saved:
            failures.append(f"{label}: mandatory deterministic check missing: {name}")
        elif saved[name].get("passed") is not True:
            failures.append(f"{label}: deterministic check failed: {name}")
        if recomputed:
            actual = recomputed.get(name)
            if actual is None or actual.get("passed") is not True:
                failures.append(f"{label}: recomputed pack check failed: {name}")
            elif name in saved and saved[name].get("passed") != actual.get("passed"):
                failures.append(f"{label}: saved check disagrees with saved actual pack: {name}")


def validate_release(root: Path, evidence_dir: Path) -> dict[str, Any]:
    """Validate current-source release evidence; returns failures and metrics."""
    root = Path(root).resolve()
    evidence = Path(evidence_dir)
    if not evidence.is_absolute():
        evidence = root / evidence
    failures: list[str] = []
    checks: list[str] = []
    warnings: list[str] = []
    metrics: dict[str, Any] = {"cases": {}}
    try:
        current: str | None = source_fingerprint(root)
        checks.append(f"RELEASE_SOURCE_FINGERPRINT={current}")
    except Exception as exc:  # noqa: BLE001
        current = None
        failures.append(f"source fingerprint unavailable: {exc}")
    from .case_registry import all_cases
    cases = {c["ticker"].upper(): c for c in all_cases()}
    expected = set(cases)
    if not evidence.is_dir():
        failures.append(f"release evidence directory missing: {evidence}")
        return {"failures": failures, "checks": checks, "warnings": warnings, "metrics": metrics}
    present = {p.name.upper() for p in evidence.iterdir() if p.is_dir() and p.name not in {"judge", "aggregate"}}
    for ticker in sorted(expected - present):
        failures.append(f"missing expected case: {ticker}")
    for ticker in sorted(present - expected):
        failures.append(f"unexpected case identity: {ticker}")
    checks.append(f"RELEASE_CASES={len(expected)}")
    arms: dict[str, dict[str, Any]] = {}
    for ticker, case in cases.items():
        arms[ticker] = {}
        for mode in MODES:
            label = f"{ticker}/{mode}"
            arm = evidence / ticker / mode
            if not arm.is_dir():
                failures.append(f"{label}: arm missing")
                continue
            summary = _json(arm / "summary.json", label, failures)
            config = _json(arm / "config.json", label, failures)
            prov = _json(arm / PROVENANCE, label, failures)
            judge = _json(evidence / "judge" / ticker / mode / "judge.json", label, failures)
            jprov = _json(evidence / "judge" / ticker / mode / PROVENANCE, label, failures)
            if not all(isinstance(x, dict) for x in (summary, config, prov, judge, jprov)):
                continue
            _provenance(prov, current, label, "run", failures)
            _provenance(jprov, current, label, "judge", failures)
            _summary(summary, ticker, mode, label, failures)
            for key, expected_value in (("llm_provider", prov.get("provider")), ("quick_think_llm", prov.get("model")), ("deep_think_llm", prov.get("model"))):
                if not config.get(key) or config.get(key) != expected_value:
                    failures.append(f"{label}: config {key} != run provenance")
            if any(config.get(k) != DEFAULT_MODEL for k in ("quick_think_llm", "deep_think_llm")):
                failures.append(f"{label}: config model is not current {DEFAULT_MODEL!r}")
            recomputed: dict[str, dict[str, Any]] = {}
            try:
                from ..evidence import EvidencePackIO
                pack = EvidencePackIO().import_pack(arm / "run")
                recomputed = _pack(pack, summary, ticker, mode, case, label, failures)
            except Exception as exc:  # noqa: BLE001
                failures.append(f"{label}: saved actual pack cannot be loaded: {exc}")
            _judge(judge, recomputed, label, failures)
            arms[ticker][mode] = {"summary": summary, "config": config, "prov": prov, "judge": judge, "jprov": jprov}
        baseline = arms[ticker].get("baseline")
        compact = arms[ticker].get("compact")
        if not baseline or not compact:
            continue
        if (baseline["prov"].get("model"), baseline["prov"].get("provider")) != (compact["prov"].get("model"), compact["prov"].get("provider")):
            failures.append(f"{ticker}: run model/provider differ across arms")
        if {k: baseline["config"].get(k) for k in SETTINGS} != {k: compact["config"].get(k) for k in SETTINGS}:
            failures.append(f"{ticker}: settings differ across arms")
        if (baseline["jprov"].get("model"), baseline["jprov"].get("provider")) != (compact["jprov"].get("model"), compact["jprov"].get("provider")):
            failures.append(f"{ticker}: judge model/provider differ across arms")
        if (baseline["prov"].get("model"), baseline["prov"].get("provider")) != (baseline["jprov"].get("model"), baseline["jprov"].get("provider")):
            failures.append(f"{ticker}: judge provenance does not match run provenance")
        metrics["cases"][ticker] = {"baseline_tokens": baseline["summary"].get("total_tokens"), "compact_tokens": compact["summary"].get("total_tokens"), "baseline_wall_seconds": baseline["summary"].get("wall_seconds"), "compact_wall_seconds": compact["summary"].get("wall_seconds"), "baseline_quality": _quality(baseline["judge"]), "compact_quality": _quality(compact["judge"])}
    paired = [m for m in metrics["cases"].values() if None not in (m["baseline_tokens"], m["compact_tokens"], m["baseline_wall_seconds"], m["compact_wall_seconds"], m["baseline_quality"], m["compact_quality"])]
    if paired:
        bt, ct, bw, cw = (sum(m[k] for m in paired) for k in ("baseline_tokens", "compact_tokens", "baseline_wall_seconds", "compact_wall_seconds"))
        reduction = 1 - ct / bt if bt > 0 else None
        ratio = cw / bw if bw > 0 else None
        bq = sum(m["baseline_quality"] for m in paired) / len(paired)
